<script setup>
import axios from 'axios'
import { computed, onMounted, onScopeDispose, reactive, ref, watch } from 'vue'
import { route } from 'ziggy-js'
import BuildingFloorPlan from './BuildingFloorPlan.vue'
import BuildingStructureManager from './BuildingStructureManager.vue'

const buildings=ref([]),cities=ref([]),buildingTypes=ref([]),loading=ref(false),referencesLoading=ref(false),saving=ref(false),error=ref(''),referenceError=ref(''),notice=ref('')
const summary=ref({}),meta=reactive({current_page:1,last_page:1,total:0,per_page:50})
const filters=reactive({search:'',city_id:null,building_type_id:null})
const searchInput=ref(null)
const dialog=ref(false),selectedBuilding=ref(null),validationErrors=ref({}),baseline=ref('')
const form=reactive({city_id:null,building_type_id:null,address:'',postcode:''})
const manager=ref(null),managerKey=ref(0)
let disposed=false,version=0,controller,searchTimer
const message=e=>Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||'Не удалось выполнить действие.'
const cityTitle=city=>[city?.name,city?.region?.name||city?.region_name].filter(Boolean).join(', ')
const range=computed(()=>meta.total?`${(meta.current_page-1)*meta.per_page+1}–${Math.min(meta.current_page*meta.per_page,meta.total)} из ${meta.total}`:'0 зданий')
async function loadBuildings(page=meta.current_page){
    clearTimeout(searchTimer);controller?.abort();controller=new AbortController();const request=++version;loading.value=true;error.value=''
    try{const {data}=await axios.get('/api/buildings',{signal:controller.signal,params:{structure:1,search:filters.search.trim()||undefined,city_id:filters.city_id||undefined,building_type_id:filters.building_type_id||undefined,page,per_page:meta.per_page}});if(disposed||request!==version)return;if(data.meta.current_page>data.meta.last_page){await loadBuildings(data.meta.last_page);return}buildings.value=data.data;summary.value=data.summary;Object.assign(meta,data.meta)}
    catch(e){if(!disposed&&request===version&&e.code!=='ERR_CANCELED')error.value=message(e)}finally{if(!disposed&&request===version)loading.value=false}
}
async function loadReferences(){referencesLoading.value=true;referenceError.value='';try{const [c,t]=await Promise.all([axios.get(route('cities.index'),{params:{itemsPerPage:-1,sortBy:[{key:'name',order:'asc'}]}}),axios.get(route('building-types.index'))]);if(disposed)return;cities.value=c.data.items??c.data.data??c.data.cities??[];buildingTypes.value=Array.isArray(t.data)?t.data:t.data.data??[]}catch(e){if(!disposed)referenceError.value=message(e)}finally{if(!disposed)referencesLoading.value=false}}
function openEdit(building=null){selectedBuilding.value=building;validationErrors.value={};Object.assign(form,{city_id:building?.city_id??null,building_type_id:building?.building_type_id??null,address:building?.address??'',postcode:building?.postcode??''});baseline.value=JSON.stringify(form);dialog.value=true}
function closeEdit(){if(!saving.value&&(JSON.stringify(form)===baseline.value||window.confirm('Закрыть без сохранения изменений здания?')))dialog.value=false}
function openStructure(building,selection={}){manager.value={buildingId:Number(building.id),initialRoomId:selection.roomId||null,initialFloorId:selection.floorId===null?'none':selection.floorId??'all'};managerKey.value++}
async function saveBuilding(){
    if(saving.value)return;validationErrors.value={};if(!form.city_id||!form.address.trim()){validationErrors.value={address:!form.address.trim()?['Укажите адрес.']:[],city_id:!form.city_id?['Выберите город.']:[]};return}
    saving.value=true;error.value='';try{const payload={...form,address:form.address.trim(),postcode:form.postcode.trim()||null,building_type_id:form.building_type_id||null};const {data}=selectedBuilding.value?await axios.patch(`/api/buildings/${selectedBuilding.value.id}`,payload):await axios.post('/api/buildings',payload);dialog.value=false;notice.value='Здание сохранено.';await loadBuildings();if(!selectedBuilding.value)openStructure(data)}catch(e){validationErrors.value=e.response?.data?.errors||{};error.value=message(e)}finally{saving.value=false}
}
async function deleteBuilding(building){if(saving.value||!window.confirm(`Удалить здание «${building.address}» и его свободные помещения? Связанные помещения удалять нельзя.`))return;saving.value=true;error.value='';try{await axios.delete(`/api/buildings/${building.id}`);notice.value='Здание удалено.';await loadBuildings()}catch(e){error.value=message(e)}finally{saving.value=false}}
function clearSearch(){filters.search='';searchInput.value?.focus()}
function schedule(){clearTimeout(searchTimer);controller?.abort();version++;loading.value=true;if(!filters.search.trim()){loadBuildings(1);return}searchTimer=setTimeout(()=>loadBuildings(1),300)}
watch(()=>filters.search,schedule)
watch([()=>filters.city_id,()=>filters.building_type_id],()=>loadBuildings(1))
onMounted(()=>{loadBuildings();loadReferences();const id=Number(new URL(window.location.href).searchParams.get('building_id'));if(Number.isInteger(id)&&id>0)openStructure({id})})
onScopeDispose(()=>{disposed=true;version++;controller?.abort();clearTimeout(searchTimer)})
</script>
<template>
<v-theme-provider theme="light"><section class="buildings-workspace" aria-label="Здания, этажи и помещения">
    <header class="buildings-heading"><h2>Buildings <span>Здания и помещения</span></h2><div class="building-inline-stats" aria-label="Статистика по фильтрам"><span><b>{{ summary.buildings??'—' }}</b> зданий</span><span><b>{{ summary.floors??'—' }}</b> этажей</span><span><b>{{ summary.apartments??'—' }}</b> помещений</span><span><b>{{ summary.entities??'—' }}</b> Entity</span><span :class="{attention:summary.without_floor}"><b>{{ summary.without_floor??'—' }}</b> без этажа</span></div><div class="heading-actions"><button :disabled="loading" @click="loadBuildings()">Обновить</button><button class="primary" @click="openEdit()">+ Здание</button></div></header>
    <div class="buildings-filterbar"><div class="buildings-search"><input ref="searchInput" v-model="filters.search" type="search" maxlength="150" aria-label="Поиск здания или помещения" placeholder="Адрес, город, номер помещения, Entity, Unit"><button v-if="filters.search" type="button" class="search-clear" aria-label="Очистить текстовый поиск" title="Очистить поиск" @click="clearSearch">×</button></div><select v-model="filters.city_id" aria-label="Фильтр по городу"><option :value="null">Все города</option><option v-for="city in cities" :key="city.id" :value="city.id">{{ cityTitle(city) }}</option></select><select v-model="filters.building_type_id" aria-label="Фильтр по типу здания"><option :value="null">Все типы</option><option v-for="type in buildingTypes" :key="type.id" :value="type.id">{{ type.name }}</option></select><button v-if="filters.search||filters.city_id||filters.building_type_id" @click="Object.assign(filters,{search:'',city_id:null,building_type_id:null})">Сбросить</button><small>{{ loading?'Загрузка…':range }}</small></div>
    <p v-if="error" class="workspace-message error" role="alert">{{ error }}</p><p v-if="referenceError" class="workspace-message error" role="alert">Справочники: {{ referenceError }} <button @click="loadReferences">Повторить</button></p><p v-if="notice" class="workspace-message success" role="status">{{ notice }} <button aria-label="Скрыть уведомление" @click="notice=''">×</button></p>
    <div class="buildings-scroll" :aria-busy="loading"><table class="buildings-table" :class="{loading}"><thead><tr><th>Здание / город</th><th>Этажи · квартиры · помещения <span>цифра справа — Entity</span></th><th>Units</th><th class="numeric">Пом. / Entity</th><th></th></tr></thead><tbody><tr v-for="building in buildings" :key="building.id"><td class="building-identity"><button class="address-button" @click="openStructure(building)">{{ building.address }}</button><small>{{ cityTitle(building.city) }}</small><div class="building-meta"><span>#{{ building.id }}</span><span>{{ building.postcode }}</span><span>{{ building.building_type?.name }}</span><a :href="`https://yandex.ru/maps/?text=${encodeURIComponent([building.city?.name,building.address].filter(Boolean).join(', '))}`" target="_blank" rel="noopener noreferrer" title="Адрес на карте">Карта ↗</a></div></td><td class="building-plan-cell"><BuildingFloorPlan :building="building" @open="openStructure(building,$event)" /></td><td class="building-units"><a v-for="unit in building.units||[]" :key="unit.id" :href="`/Ameise/unit/${unit.id}`">{{ unit.name }} ↗</a><span v-if="!building.units?.length">—</span></td><td class="numeric"><b>{{ building.apartments?.length||0 }}</b><small>{{ new Set((building.apartments||[]).flatMap(r=>(r.entities||[]).map(e=>e.id))).size }} Entity</small></td><td class="row-actions"><button @click="openStructure(building)">Этажи</button><div><button :aria-label="`Изменить здание ${building.address}`" @click="openEdit(building)">✎</button><button class="danger" :disabled="saving" :aria-label="`Удалить здание ${building.address}`" @click="deleteBuilding(building)">×</button></div></td></tr><tr v-if="!buildings.length"><td colspan="5" class="buildings-empty">{{ loading?'Загрузка зданий…':'Зданий по выбранным условиям нет.' }}</td></tr></tbody></table></div>
    <footer class="buildings-footer"><span>Нажмите на этаж или помещение для управления. Зелёные помещения связаны с Entity.</span><div><label>Строк <select v-model="meta.per_page" aria-label="Зданий на странице" @change="loadBuildings(1)"><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option></select></label><button :disabled="loading||meta.current_page<=1" @click="loadBuildings(meta.current_page-1)">←</button><span>{{ meta.current_page }} / {{ meta.last_page }}</span><button :disabled="loading||meta.current_page>=meta.last_page" @click="loadBuildings(meta.current_page+1)">→</button></div></footer>
    <v-dialog :model-value="Boolean(manager)" persistent width="96vw" max-width="1550"><BuildingStructureManager v-if="manager" :key="managerKey" v-bind="manager" @close="manager=null" @changed="loadBuildings()" /></v-dialog>
    <v-dialog v-model="dialog" persistent max-width="620"><section class="building-editor"><header><h3>{{ selectedBuilding?'Изменить здание':'Новое здание' }}</h3><button :disabled="saving" aria-label="Закрыть редактор здания" @click="closeEdit">×</button></header><form @submit.prevent="saveBuilding"><p v-if="error" class="error">{{ error }}</p><v-autocomplete v-model="form.city_id" :items="cities" :item-title="cityTitle" item-value="id" label="Город" variant="outlined" density="compact" :error-messages="validationErrors.city_id" :loading="referencesLoading" :disabled="saving" /><label>Адрес<input v-model="form.address" required maxlength="255" :disabled="saving"></label><small class="error">{{ validationErrors.address?.join(' ') }}</small><div class="editor-pair"><label>Индекс<input v-model="form.postcode" maxlength="32" :disabled="saving"></label><label>Тип<select v-model="form.building_type_id" :disabled="saving"><option :value="null">Не указан</option><option v-for="type in buildingTypes" :key="type.id" :value="type.id">{{ type.name }}</option></select></label></div><footer><button type="button" :disabled="saving" @click="closeEdit">Отмена</button><button class="primary" :disabled="saving">Сохранить здание</button></footer></form></section></v-dialog>
</section></v-theme-provider>
</template>
<style scoped>
.buildings-workspace{color:#3f4d58;background:#fff;border:1px solid #dce2e8;border-radius:6px;font:11px/1.4 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;min-width:0;min-height:0;flex:1;display:flex;flex-direction:column;overflow:hidden}.buildings-heading{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:8px 10px;border-bottom:1px solid #e6eaee;background:#fafbfc}.buildings-heading h2{margin:0;font-size:15px;font-weight:600;white-space:nowrap}.buildings-heading h2 span{font-size:10px;color:#9aa3ac;font-weight:400;margin-left:5px}.building-inline-stats{display:flex;flex-wrap:wrap;gap:12px;flex:1;color:#8b969f;font-size:10px}.building-inline-stats b{font-size:12px;color:#5c6e7d;font-weight:600;margin-right:2px}.building-inline-stats .attention{color:#b0915e}.heading-actions{display:flex;gap:5px}.buildings-filterbar{display:flex;align-items:center;gap:6px;flex-wrap:wrap;padding:7px 10px;border-bottom:1px solid #e4e9ed}.buildings-search{position:relative;flex:1 1 270px;min-width:0}.buildings-search input{width:100%;padding-right:32px}.buildings-search input::-webkit-search-cancel-button{appearance:none}.buildings-search .search-clear{position:absolute;right:3px;top:50%;transform:translateY(-50%);min-height:22px;width:24px;padding:0;border:0;background:transparent;font-size:17px}.buildings-filterbar>select{width:200px}.buildings-filterbar>select:nth-of-type(2){width:150px}.buildings-filterbar>small{margin-left:auto;font-size:10px;color:#929ca6}.buildings-heading,.buildings-filterbar,.workspace-message,.buildings-footer{flex-shrink:0}.buildings-scroll{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain}.buildings-table{width:100%;min-width:850px;border-collapse:collapse;text-align:left;font-size:11px}.buildings-table.loading{opacity:.5;pointer-events:none}.buildings-table th{position:sticky;top:0;z-index:1;padding:6px 8px;background:#eef2f5;color:#7c8a96;font-weight:500;font-size:10px;white-space:nowrap;border-bottom:1px solid #dce2e8}.buildings-table th span{font-size:9px;font-weight:400;color:#9da7af;margin-left:7px}.buildings-table td{padding:6px 8px;vertical-align:top;border-bottom:1px solid #e9edf0}.buildings-table tbody tr:nth-child(even){background:#fcfdfe}.buildings-table tbody tr:hover{background:#f7fafd}.building-identity{width:260px;max-width:320px}.address-button{font-size:11px!important;font-weight:600;border:0!important;background:transparent!important;padding:0!important;min-height:18px!important;text-align:left;white-space:normal!important;color:#4a6478!important}.building-identity>small,.numeric small{display:block;font-size:10px;color:#909ca5;margin-top:3px}.building-meta{display:flex;gap:6px;flex-wrap:wrap;margin-top:5px;color:#a3adb5;font-size:9px}.building-plan-cell{min-width:300px}.building-units{width:170px;max-width:210px}.building-units a{display:block;font-size:10px;color:#809581;text-decoration:none;margin-bottom:3px;overflow-wrap:anywhere}.building-units>span{color:#b3bdc5}.numeric{text-align:right;font-variant-numeric:tabular-nums;width:95px}.numeric b{font-weight:500;color:#6d7e8a}.row-actions{width:75px}.row-actions>button{width:100%;font-size:10px;min-height:23px}.row-actions>div{display:flex;gap:4px;justify-content:flex-end;margin-top:3px}.row-actions>div button{padding:1px 6px;min-height:20px}.buildings-empty{text-align:center;padding:30px!important;color:#a1aab2}.buildings-footer{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;padding:6px 10px;background:#fafbfd;color:#97a2ac;font-size:10px}.buildings-footer>div,.buildings-footer label{display:flex;align-items:center;gap:6px}.buildings-footer select{width:62px;min-height:24px;font-size:10px}.buildings-footer button{min-height:24px}.workspace-message{margin:0;padding:6px 10px}.workspace-message button{min-height:20px;padding:0 6px}.error{color:#a45d66;background:#fff4f4}.success{color:#5a8264;background:#f1f8f2}button,input,select{font:inherit}button{border:1px solid #d8e0e7;background:#fff;padding:3px 8px;border-radius:4px;min-height:27px;color:#6e8090;cursor:pointer;white-space:nowrap}button:hover:enabled{background:#eaf1f7}button:disabled{opacity:.45;cursor:default}.primary{background:#647f9d;color:#fff;border-color:#647f9d}.danger{color:#b7737b}input,select{min-width:0;min-height:28px;border:1px solid #dae2e9;border-radius:4px;padding:4px 7px;background:#fff;color:#566b7d}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #97b2d2;outline-offset:2px}.building-editor{background:white;color:#536370;border-radius:8px;font:12px/1.4 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-height:90dvh;overflow:auto}.building-editor header{display:flex;align-items:center;justify-content:space-between;padding:12px 15px;border-bottom:1px solid #e2e7ed}.building-editor h3{font-size:15px;margin:0}.building-editor form{padding:15px;display:grid;gap:10px}.building-editor label{display:grid;gap:4px}.editor-pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}.building-editor footer{display:flex;justify-content:flex-end;gap:7px;margin-top:8px}@media(max-width:800px){.buildings-heading h2 span{display:none}.building-inline-stats{order:2;flex-basis:100%;gap:9px}.heading-actions{margin-left:auto}.buildings-filterbar>select{flex:1;max-width:50%;width:auto}.buildings-footer>span{display:none}}
</style>
